<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Transactions</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>@media print{nav,.filters,.no-print{display:none!important}body{background:#fff}.container{max-width:none}}</style></head><body class="bg-light"><main class="container py-4"><nav class="mb-3"><a href="<?= base_url('reports') ?>">Reports</a> / Daily Transactions</nav><h1 class="h3">Daily Transactions Report</h1><form class="row g-2 my-3 filters"><div class="col-auto"><label class="form-label">Date</label><input class="form-control" type="date" name="date" value="<?= esc($filters['date']) ?>"></div><div class="col-auto"><label class="form-label">Type</label><select class="form-select" name="type"><option value="">All types</option><?php foreach (['DEPOSIT','WITHDRAWAL','TRANSFER','LOAN_DISBURSEMENT','LOAN_REPAYMENT','INTEREST_CREDIT','FEE','ADJUSTMENT'] as $type): ?><option <?= $filters['type']===$type?'selected':'' ?>><?= esc($type) ?></option><?php endforeach ?></select></div><div class="col-auto"><label class="form-label">Branch</label><select class="form-select" name="branch_id"><option value="">All branches</option><?php foreach($branches as $branch): ?><option value="<?= esc($branch['id']) ?>" <?= $filters['branch_id']===(int)$branch['id']?'selected':'' ?>><?= esc($branch['name']) ?></option><?php endforeach ?></select></div><div class="col-auto align-self-end"><button class="btn btn-primary">Filter</button><button type="button" class="btn btn-outline-secondary" onclick="window.print()">Print Report</button></div></form><p><span class="badge text-bg-primary">Total Count: <?= number_format($totalCount) ?></span> <span class="badge text-bg-success">Total Amount: Rs. <?= number_format($totalAmount,2) ?></span></p><div class="table-responsive bg-white"><table class="table table-striped"><thead><tr><th>Date</th><th>Reference</th><th>Account</th><th>Type</th><th>Branch</th><th>Amount (LKR)</th><th>Status</th></tr></thead><tbody><?php foreach($transactions as $row): ?><tr><td><?= esc($row['tx_date'] ?? '') ?></td><td><?= esc($row['tx_id'] ?? '') ?></td><td><?= esc($row['account_no'] ?? '—') ?></td><td><?= esc($row['type'] ?? '') ?></td><td><?= esc($row['branch_name'] ?? '—') ?></td><td>Rs. <?= number_format((float)($row['amount'] ?? 0),2) ?></td><td><span class="badge text-bg-<?= ($row['status'] ?? '')==='POSTED'?'success':'secondary' ?>"><?= esc($row['status'] ?? '') ?></span></td></tr><?php endforeach ?><?php if(!$transactions): ?><tr><td colspan="7" class="text-center text-secondary">No transactions found.</td></tr><?php endif ?></tbody></table></div></main></body></html>
